-- Absolute ZRO · mudança do banco para São Paulo · passo 3: copiar os dados (e conferir sozinho)
-- RODE NO PROJETO: AbsoluteZRO-SP (São Paulo, ref njvhgycmbuhimxovxuqj)  <-- o NOVO.
--
-- O que faz, numa transação só (deu erro = nada muda no NOVO; o ANTIGO nunca é alterado, só lido):
--   1. conecta no ANTIGO com o login temporário migracao_sp (passo 1);
--   2. apaga o que houver nas tabelas dos apps no NOVO (para poder rodar de novo na cópia final);
--   3. copia tabela por tabela (sem disparar gatilhos: as tabelas que "só crescem" aceitam a carga);
--   4. copia a conta do NOSSOM em auth.users/auth.identities (se já existir, mantém);
--   5. acerta os contadores (sequências) com os valores do ANTIGO;
--   6. CONFERE cada tabela nos dois lados (quantidade de linhas e md5 do conteúdo). Diferiu = cancela tudo.
--
-- ANTES DE RODAR: na linha que começa com "select extensions.dblink_connect":
--   1. troque SENHA_DO_MIGRACAO_SP pela senha que VOCÊ escolheu no passo 1 (não mande para ninguém);
--   2. confira o host: tem de ser o mesmo do "Session pooler" do projeto ANTIGO (AbsoluteZRO > Connect >
--      Session pooler). O kit já vem com aws-0-us-east-2.pooler.supabase.com; se lá aparecer outro, troque.
-- Depois de rodar, apague a senha deste texto (ou feche a aba sem salvar).

do $guarda$ begin
  if exists (select 1 from pg_roles where rolname = 'migracao_sp') then
    raise exception 'PARE: você está no projeto ANTIGO (AbsoluteZRO). Este arquivo roda só no AbsoluteZRO-SP.';
  end if;
  if to_regclass('zro.schema_migrations') is null or to_regclass('sobedesce.__drizzle_migrations') is null or to_regclass('carro_do_freela.passos') is null then
    raise exception 'PARE: a estrutura ainda não está completa aqui. Rode os passos 2a a 2e e o 4 antes.';
  end if;
end $guarda$;

create extension if not exists dblink with schema extensions;
set local search_path to pg_catalog, extensions;
set local session_replication_role = replica;
set local timezone = 'UTC'; set local datestyle = 'ISO, MDY'; set local intervalstyle = 'postgres';
set local extra_float_digits = 1; set local bytea_output = 'hex';
set local statement_timeout = 0;

select extensions.dblink_connect('velho', 'host=aws-0-us-east-2.pooler.supabase.com port=5432 dbname=postgres user=migracao_sp.eudeffnxzqlxixvmnija password=SENHA_DO_MIGRACAO_SP sslmode=require');
select extensions.dblink_exec('velho', 'set timezone = ''UTC''; set datestyle = ''ISO, MDY''; set intervalstyle = ''postgres''; set extra_float_digits = 1; set bytea_output = ''hex''; set statement_timeout = 0');
select extensions.dblink_exec('velho', 'begin isolation level repeatable read read only');
-- a mesma foto do ANTIGO para a cópia e para a conferência (transação de leitura no ANTIGO)

do $guarda$ begin
  if (select n from extensions.dblink('velho', 'select count(*) from pg_roles where rolname = ''migracao_sp''') as r(n bigint)) <> 1 then
    raise exception 'PARE: a conexão não chegou no projeto ANTIGO certo.';
  end if;
end $guarda$;

do $guarda$ begin
  -- depois da virada o NOVO passa a receber gravações: rodar a cópia de novo apagaria essas gravações
  if coalesce((select max(created_at) from zro.audit_logs), '-infinity') >
     coalesce((select m from extensions.dblink('velho', 'select max(created_at) from zro.audit_logs') as r(m timestamptz)), '-infinity')
  or coalesce((select max(created_at) from maestro.audit_log), '-infinity') >
     coalesce((select m from extensions.dblink('velho', 'select max(created_at) from maestro.audit_log') as r(m timestamptz)), '-infinity') then
    raise exception 'PARE: o NOVO já tem gravações mais novas que o ANTIGO (a virada já aconteceu). Não rode a cópia de novo.';
  end if;
end $guarda$;

