  select * from extensions.dblink('velho', 'select "instance_id", "id", "aud", "role", "email", "encrypted_password", "email_confirmed_at", "invited_at", "confirmation_token", "confirmation_sent_at", "recovery_token", "recovery_sent_at", "email_change_token_new", "email_change", "email_change_sent_at", "last_sign_in_at", "raw_app_meta_data", "raw_user_meta_data", "is_super_admin", "created_at", "updated_at", "phone", "phone_confirmed_at", "phone_change", "phone_change_token", "phone_change_sent_at", "email_change_token_current", "email_change_confirm_status", "banned_until", "reauthentication_token", "reauthentication_sent_at", "is_sso_user", "deleted_at", "is_anonymous" from migracao_sp_leitura.auth_users')
  as r("instance_id" uuid, "id" uuid, "aud" character varying(255), "role" character varying(255), "email" character varying(255), "encrypted_password" character varying(255), "email_confirmed_at" timestamp with time zone, "invited_at" timestamp with time zone, "confirmation_token" character varying(255), "confirmation_sent_at" timestamp with time zone, "recovery_token" character varying(255), "recovery_sent_at" timestamp with time zone, "email_change_token_new" character varying(255), "email_change" character varying(255), "email_change_sent_at" timestamp with time zone, "last_sign_in_at" timestamp with time zone, "raw_app_meta_data" jsonb, "raw_user_meta_data" jsonb, "is_super_admin" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "phone" text, "phone_confirmed_at" timestamp with time zone, "phone_change" text, "phone_change_token" character varying(255), "phone_change_sent_at" timestamp with time zone, "email_change_token_current" character varying(255), "email_change_confirm_status" smallint, "banned_until" timestamp with time zone, "reauthentication_token" character varying(255), "reauthentication_sent_at" timestamp with time zone, "is_sso_user" boolean, "deleted_at" timestamp with time zone, "is_anonymous" boolean)
  on conflict do nothing;
insert into "auth"."identities" ("provider_id", "user_id", "identity_data", "provider", "last_sign_in_at", "created_at", "updated_at", "id")
  select * from extensions.dblink('velho', 'select "provider_id", "user_id", "identity_data", "provider", "last_sign_in_at", "created_at", "updated_at", "id" from migracao_sp_leitura.auth_identities')
  as r("provider_id" text, "user_id" uuid, "identity_data" jsonb, "provider" text, "last_sign_in_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "id" uuid)
  on conflict do nothing;

