-- ===== conferência: linhas e md5 do conteúdo, tabela por tabela, nos dois lados =====
create temp table _conferencia (tabela text primary key, linhas_antigo bigint, linhas_novo bigint, md5_antigo text, md5_novo text) on commit drop;
insert into _conferencia select 'carro_do_freela.cadastros', r.n, l.n, r.h, l.h from extensions.dblink('velho', 'select count(*), md5(coalesce(string_agg(x::text, E''\n'' order by x::text collate "C"), '''')) from (select "id", "quando", "quem", "lado", "nome", "praca", "funcoes", "contato", "versao" from "carro_do_freela"."cadastros") x') as r(n bigint, h text), (select count(*), md5(coalesce(string_agg(x::text, E'\n' order by x::text collate "C"), '')) from (select "id", "quando", "quem", "lado", "nome", "praca", "funcoes", "contato", "versao" from "carro_do_freela"."cadastros") x) as l(n, h);
insert into _conferencia select 'carro_do_freela.leads', r.n, l.n, r.h, l.h from extensions.dblink('velho', 'select count(*), md5(coalesce(string_agg(x::text, E''\n'' order by x::text collate "C"), '''')) from (select "id", "criado_em", "lado", "nome", "whatsapp", "praca", "funcao", "tipo_negocio", "jobs_mes", "aceite_contato", "aceite_publicacao", "dias_livres" from "carro_do_freela"."leads") x') as r(n bigint, h text), (select count(*), md5(coalesce(string_agg(x::text, E'\n' order by x::text collate "C"), '')) from (select "id", "criado_em", "lado", "nome", "whatsapp", "praca", "funcao", "tipo_negocio", "jobs_mes", "aceite_contato", "aceite_publicacao", "dias_livres" from "carro_do_freela"."leads") x) as l(n, h);
insert into _conferencia select 'carro_do_freela.passos', r.n, l.n, r.h, l.h from extensions.dblink('velho', 'select count(*), md5(coalesce(string_agg(x::text, E''\n'' order by x::text collate "C"), '''')) from (select "id", "quando", "quem", "passo", "lado", "volta", "versao" from "carro_do_freela"."passos") x') as r(n bigint, h text), (select count(*), md5(coalesce(string_agg(x::text, E'\n' order by x::text collate "C"), '')) from (select "id", "quando", "quem", "passo", "lado", "volta", "versao" from "carro_do_freela"."passos") x) as l(n, h);
