insert into _conferencia select 'auth.users', r.n, r.n, 'n/a', 'n/a' from extensions.dblink('velho', 'select count(*) from migracao_sp_leitura.auth_users') as r(n bigint);
update _conferencia set linhas_novo = (select count(*) from "auth"."users" where id in (select r.id from extensions.dblink('velho', 'select id from migracao_sp_leitura.auth_users') as r(id uuid))) where tabela = 'auth.users';
insert into _conferencia select 'auth.identities', r.n, r.n, 'n/a', 'n/a' from extensions.dblink('velho', 'select count(*) from migracao_sp_leitura.auth_identities') as r(n bigint);
update _conferencia set linhas_novo = (select count(*) from "auth"."identities" where id in (select r.id from extensions.dblink('velho', 'select id from migracao_sp_leitura.auth_identities') as r(id uuid))) where tabela = 'auth.identities';

select extensions.dblink_exec('velho', 'commit');
select extensions.dblink_disconnect('velho');

do $confere$
declare v text;
begin
  select string_agg(tabela || ' (antigo ' || linhas_antigo || ', novo ' || linhas_novo || ')', '; ' order by tabela) into v
  from _conferencia where linhas_antigo is distinct from linhas_novo or md5_antigo is distinct from md5_novo;
  if v is not null then
    raise exception 'PARE: a cópia não bateu e foi desfeita (nada mudou no NOVO). Tabelas: %', v;
  end if;
end $confere$;

select 'ok: ' || count(*) || ' tabelas copiadas e conferidas (' || sum(linhas_novo) || ' linhas). Pode seguir.' as resultado from _conferencia;
